//! The GM command registry, tokenizer and dispatcher (Plan/23 §3-§4; WP-GM-04).
//!
//! * [`table`]: `COMMANDS`, one [`CommandSpec`] per legacy row 1..=219 plus the new commands N01..N16 and the repository's
//!   N17 `/content` (generated by `tools/gen_gm_table.py` from the plan tables);
//! * [`CommandRegistry`]: the case-insensitive lookup of names and aliases (PL-113);
//! * [`dispatch_line`]: `/command args` for a player, an item, the console or the admin API; the authority gate
//!   (VR-073) behaves exactly like an unknown command and is audited as `denied`;
//! * [`CmdArgs`] (`args`), the target resolution (`target`), the `OutLine` mapping and text rendering (`text`),
//!   the `gm.command` audit (`audit`), and the handlers (`cmd`).
//!
//! A row whose handler is not written yet is `Deferred("<WP>")` in the table and behaves like an unknown
//! command; each later WP regenerates the table with its handler.

pub mod admin;
pub mod args;
pub mod audit;
pub mod cmd;
pub mod export;
pub mod item_text;
pub mod lookup;
pub mod modes;
pub mod rates;
pub mod requests;
pub mod table;
pub mod target;
pub mod text;

pub use admin::GmAdmin;
pub use args::CmdArgs;
pub use requests::{GmRequest, ServerRequest, ServerRequestSink};
