/// Where a command runs (23 §3.2).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CmdSide {
    /// Only the server executes it.
    Server,
    /// Intercepted and executed by the browser; never executed on the server.
    Client,
    /// The browser may add a convenience (window, rewrite); the server executes it.
    Both,
}

/// The runtime state of a table row (23 §3.2).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CmdStatus {
    /// Implemented: the handler runs.
    Port,
    /// The browser executes it.
    Client,
    /// Never implemented (the reason is the plan's).
    Drop(&'static str),
    /// Not compiled into the original (`_DEBUG`, `__GUILDRANK`, ...).
    Inactive(&'static str),
    /// A `PORT` row whose handler is the named WP's (or a deferred decision such as PL-147): behaves like an
    /// unknown command.
    Deferred(&'static str),
}

/// The decision column of the plan table (23 §4.0, §4.10).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Dec {
    /// `PORT`.
    Port,
    /// `PORT*` (with a ledger row).
    PortFix,
    /// `SIMPL`.
    Simpl,
    /// `CLIENT`.
    Client,
    /// `DEFER`.
    Defer,
    /// `DROP`.
    Drop,
    /// `INACT`.
    Inact,
    /// A new command (N01..N16, and the repository's N17).
    New,
}

/// One command (23 §3.2).
#[derive(Clone, Copy)]
pub struct CommandSpec {
    /// The legacy row 1..=219, 0 for a new command.
    pub row: u16,
    /// The canonical English long name, original spelling (shown by `/help`).
    pub name: &'static str,
    /// The legacy and new aliases, matched case-insensitively.
    pub aliases: &'static [&'static str],
    /// The minimum authority.
    pub min_auth: Authority,
    /// Where it runs.
    pub side: CmdSide,
    /// The runtime state.
    pub status: CmdStatus,
    /// The plan's decision for the row.
    pub dec: Dec,
    /// Needs an in-world issuer character ("self").
    pub needs_self: bool,
    /// On the item-privilege whitelist (PL-114, §5).
    pub item_ok: bool,
    /// `"<name> <text...>"`.
    pub usage: &'static str,
    /// One line for `/help`.
    pub help: &'static str,
    /// The milestone in which it must work.
    pub milestone: u8,
    /// `None` for client, dropped, inactive and deferred rows.
    pub handler: Option<CmdHandler>,
}

impl std::fmt::Debug for CommandSpec {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("CommandSpec")
            .field("row", &self.row)
            .field("name", &self.name)
            .field("status", &self.status)
            .finish_non_exhaustive()
    }
}

/// A command handler: runs with the issuer's context and the tokenizer positioned after the command name.
pub type CmdHandler = fn(&mut CmdCtx<'_, '_>, &mut CmdArgs<'_>) -> CmdResult;

/// What a handler returns.
pub type CmdResult = Result<CmdDone, CmdError>;

/// A successful run.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct CmdDone {
    /// The target name for the audit record.
    pub target: Option<String>,
}

impl CmdDone {
    /// A run that names a target.
    pub fn on(target: impl Into<String>) -> Self {
        Self {
            target: Some(target.into()),
        }
    }
}

/// Why a handler did not run to completion (23 §3.4 step 7).
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum CmdError {
    /// A new command with bad arguments: `Text("Usage: /<name> <usage>")`.
    Usage,
    /// A name that does not exist: `ReturnSay{3, name}`.
    NotFound(String),
    /// A known character that is not online: `DefinedText(TID_GAME_NOTLOGIN)`.
    Offline(String),
    /// A self target: `ReturnSay{2, " "}`.
    NotSelf,
    /// A refusal with a free text.
    Refused(String),
    /// The command needs a character and the issuer has none.
    NeedsSelf,
    /// An unexpected failure.
    Internal(String),
}

/// Who runs a command (23 §3.2).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Issuer {
    /// A player typed it.
    Player {
        /// The socket.
        session: SessionId,
        /// The avatar.
        player: PlayerRef,
    },
    /// An item with a GM text was used (23 §5).
    Item {
        /// The socket.
        session: SessionId,
        /// The avatar.
        player: PlayerRef,
        /// The item id.
        item: u32,
    },
    /// The stdin console (acts as administrator).
    Console,
    /// An identity of the admin HTTP API: an owner (acts as administrator) or a staff member of the admin console
    /// (acts with its own authority letter, 25 §1.4). Never `Console` or `Cli`: those run as [`Issuer::Console`].
    Admin {
        /// The identity (`AdminActor::Owner` or `AdminActor::Staff`).
        actor: crate::input::AdminActor,
    },
}

impl Issuer {
    fn tag(&self) -> &'static str {
        match self {
            Issuer::Player { .. } => "player",
            Issuer::Item { .. } => "item",
            Issuer::Console => "console",
            Issuer::Admin { .. } => "admin_api",
        }
    }

    /// The avatar that receives the output, if any.
    pub fn player(&self) -> Option<PlayerRef> {
        match self {
            Issuer::Player { player, .. } | Issuer::Item { player, .. } => Some(*player),
            _ => None,
        }
    }
}

/// The context of one command run (23 §3.2, over the split borrows of 10 §4.1.1).
pub struct CmdCtx<'a, 'g> {
    /// The services.
    pub svc: &'a mut Services,
    /// The game context.
    pub ctx: &'a mut GameCtx<'g>,
    /// Who runs it.
    pub issuer: Issuer,
    /// The effective authority of the gate (23 §3.4 step 6).
    pub authority: Authority,
    /// The in-world character acting as "self" (the player, the item user, or the `as <name>` character).
    pub self_player: Option<PlayerRef>,
    /// The collected output.
    pub out: CmdOutput,
    /// The line came from a shortcut/macro slot (`ChatReq.shortcut`).
    pub shortcut: bool,
}

/// `dispatch_line` result (23 §3.2).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DispatchOutcome {
    /// A command ran (or was refused with its own reply).
    Handled,
    /// Not a command (unknown, unauthorised, client-only, dropped, deferred, empty): the caller routes it
    /// (23 §3.6, [`route_unknown`]).
    NotACommand,
}

/// What the caller does with a line that is not a command (23 §3.6).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Routing {
    /// Route the line as normal chat without the spam check and the filter.
    AsChat,
    /// The "Unknown command" reply was queued; nothing is broadcast.
    Replied,
}

/// The lookup of names and aliases (23 §3.3).
#[derive(Debug)]
pub struct CommandRegistry {
    specs: &'static [CommandSpec],
    by_key: DetMap<String, usize>,
}

impl CommandRegistry {
    /// Builds the registry of [`table::COMMANDS`]. Every `name` and alias of every row that is not an inactive,
    /// dropped or empty entry is a key (lower-cased); a duplicate key is a programming error (unit-tested).
    pub fn build() -> CommandRegistry {
        Self::from_specs(table::COMMANDS).unwrap_or_else(|dup| {
            tracing::error!(key = %dup, "duplicate command key in the GM table");
            CommandRegistry {
                specs: &[],
                by_key: DetMap::default(),
            }
        })
    }

    /// Builds a registry over `specs`; `Err(key)` names the first duplicate.
    pub fn from_specs(specs: &'static [CommandSpec]) -> Result<CommandRegistry, String> {
        let mut by_key: DetMap<String, usize> = DetMap::default();
        for (i, s) in specs.iter().enumerate() {
            for k in std::iter::once(s.name).chain(s.aliases.iter().copied()) {
                if k.is_empty() {
                    continue;
                }
                if by_key.insert(k.to_ascii_lowercase(), i).is_some() {
                    return Err(k.to_ascii_lowercase());
                }
            }
        }
        Ok(CommandRegistry { specs, by_key })
    }

    /// The row of a command token, ASCII case-insensitive.
    pub fn lookup(&self, token: &str) -> Option<&'static CommandSpec> {
        if token.is_empty() {
            return None;
        }
        self.by_key
            .get(&token.to_ascii_lowercase())
            .and_then(|&i| self.specs.get(i))
    }

    /// The commands `a` may run and the browser lists (`status` `Port` or `Client`, `min_auth <= a`), sorted by
    /// minimum authority then name (`/help`, the auto-complete export).
    pub fn visible_to(&self, a: Authority) -> Vec<&'static CommandSpec> {
        let mut v: Vec<&'static CommandSpec> = self
            .specs
            .iter()
            .filter(|s| {
                matches!(s.status, CmdStatus::Port | CmdStatus::Client) && a.at_least(s.min_auth)
            })
            .collect();
        v.sort_by(|x, y| {
            (x.min_auth, x.name.to_ascii_lowercase())
                .cmp(&(y.min_auth, y.name.to_ascii_lowercase()))
        });
        v
    }
}

/// Doc 22's `IsInstanceDungeon(world)` as `/teleport` needs it (Plan/23 row 28): a world that is an instance
/// dungeon can only be entered by a GM who is already in it.
pub trait InstanceWorlds: Send + std::fmt::Debug {
    /// `true` when `world` is an instance-dungeon world.
    fn is_instance_world(&self, world: flyff_common::WorldId) -> bool;
}

/// The default: no world is an instance dungeon (until doc 22 installs its registry).
#[derive(Debug, Default)]
pub struct NoInstances;

impl InstanceWorlds for NoInstances {
    fn is_instance_world(&self, _world: flyff_common::WorldId) -> bool {
        false
    }
}

/// A `ShutdownHandle` standing in for the one of `GameInit` (see [`GmService::shutdown_override`]).
pub struct ShutdownOverride(pub Box<dyn flyff_common::rt::ShutdownHandle>);

impl std::fmt::Debug for ShutdownOverride {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str("ShutdownOverride(..)")
    }
}

/// The GM state of the game (`Services.gm`).
#[derive(Debug)]
pub struct GmService {
    /// The registry (shared so a handler can run while `svc` is borrowed).
    pub registry: Arc<CommandRegistry>,
    /// The audit recorder of tests.
    pub tap: AuditTap,
    /// The instance-dungeon lookup of `/teleport` (doc 22 replaces [`NoInstances`]).
    pub instances: Box<dyn InstanceWorlds>,
    /// Effects the handlers could not run themselves (`Game::drain_gm_requests`).
    pub requests: Vec<GmRequest>,
    /// A replacement for the `ShutdownHandle` of `GameInit` (tests feed `GameInput::Shutdown` back to the game
    /// with it; the server leaves it `None`).
    pub shutdown_override: Option<ShutdownOverride>,
    /// The validated command texts of the `IK2_GMTEXT` items (23 §5.1, WP-GM-19); built at game start.
    pub item_text: item_text::GmItemCommands,
    /// The side channel of the account changes (`/ban`, `/setauth`) to the admin console (25 §1.8).
    pub account_events: crate::input::AccountEventSink,
    /// What the GM commands ask of the server: the disk read of `scripts/npc/` and the file reload (WP-GM-25).
    pub server_requests: ServerRequestSink,
}

impl Default for GmService {
    fn default() -> Self {
        Self {
            registry: Arc::new(CommandRegistry::build()),
            tap: AuditTap::default(),
            instances: Box::new(NoInstances),
            requests: Vec::new(),
            shutdown_override: None,
            item_text: item_text::GmItemCommands::default(),
            account_events: crate::input::AccountEventSink::default(),
            server_requests: ServerRequestSink::default(),
        }
    }
}

impl GmService {
    /// Queues a deferred effect.
    pub fn request(&mut self, r: GmRequest) {
        self.requests.push(r);
    }

    /// Records `event` on the audit tap of the tests (nothing when the tap is off).
    pub fn record(&mut self, event: &str, detail: serde_json::Value) {
        if self.tap.enabled {
            self.tap.events.push((event.to_owned(), detail));
        }
    }
}

/// `dispatch_line` (23 §3.4): `line` starts with `/` (console and admin lines get one first). Runs the handler
/// of the command and queues its output in `cx.out`; audits `gm.command` where §3.9 says so.
pub fn dispatch_line(
    cx: &mut CmdCtx<'_, '_>,
    reg: &CommandRegistry,
    line: &str,
) -> DispatchOutcome {
    let mut args = CmdArgs::new(line);
    let slash = args.token().to_owned();
    // an empty first token (`//...` is a comment, a blank line) is not a command; the token must be the slash
    if slash != "/" {
        return DispatchOutcome::NotACommand;
    }
    let tok = args.token().to_owned();
    if tok.is_empty() {
        return DispatchOutcome::NotACommand;
    }
    let player_issuer = matches!(cx.issuer, Issuer::Player { .. } | Issuer::Item { .. });
    let Some(spec) = reg.lookup(&tok) else {
        audit::unknown(cx, line);
        return DispatchOutcome::NotACommand;
    };
    // 3. a client-only row: a non-browser client sent it
    if spec.side == CmdSide::Client || spec.status == CmdStatus::Client {
        if player_issuer {
            audit::command(cx, spec, line, "unknown", None);
            return DispatchOutcome::NotACommand;
        }
        cx.out.text("client-side command");
        return DispatchOutcome::Handled;
    }
    // 4. dropped, inactive or deferred rows
    if let CmdStatus::Drop(r) | CmdStatus::Inactive(r) | CmdStatus::Deferred(r) = spec.status {
        if player_issuer {
            audit::command(cx, spec, line, "unknown", None);
            return DispatchOutcome::NotACommand;
        }
        cx.out.text(format!("{}: not available ({r})", spec.name));
        return DispatchOutcome::Handled;
    }
    // 6. the authority gate (VR-073); items bypass it for the whitelist when `fidelity.item_gm_commands`
    let item_bypass = matches!(cx.issuer, Issuer::Item { .. })
        && cx.ctx.cfg.rules.fidelity.item_gm_commands
        && spec.item_ok;
    if !(item_bypass || cx.authority.at_least(spec.min_auth)) {
        audit::command(cx, spec, line, "denied", None);
        return DispatchOutcome::NotACommand;
    }
    // 5. the "self" character
    if spec.needs_self && cx.self_player.is_none() {
        cx.out
            .text("this command needs a character: use 'as <name> ...'");
        audit::command(cx, spec, line, "refused", None);
        return DispatchOutcome::Handled;
    }
    // 7. run
    let Some(handler) = spec.handler else {
        audit::command(cx, spec, line, "unknown", None);
        return DispatchOutcome::NotACommand;
    };
    let result = handler(cx, &mut args);
    let (res, target) = match result {
        Ok(done) => ("ok", done.target),
        Err(CmdError::Usage) => {
            cx.out
                .text(format!("Usage: /{} {}", spec.name, spec.usage).trim_end());
            ("usage", None)
        }
        Err(CmdError::NotFound(n)) => {
            cx.out.return_say(3, &n);
            ("not_found", Some(n))
        }
        Err(CmdError::Offline(n)) => {
            cx.out
                .defined(flyff_common::defs::text::TID_GAME_NOTLOGIN, Vec::new());
            ("offline", Some(n))
        }
        Err(CmdError::NotSelf) => {
            cx.out.return_say(2, " ");
            ("refused", None)
        }
        Err(CmdError::Refused(m)) => {
            cx.out.text(m);
            ("refused", None)
        }
        Err(CmdError::NeedsSelf) => {
            cx.out
                .text("this command needs a character: use 'as <name> ...'");
            ("refused", None)
        }
        Err(CmdError::Internal(e)) => {
            tracing::error!(command = spec.name, error = %e, "GM command failed");
            cx.out.text("internal error");
            ("error", None)
        }
    };
    audit::command(cx, spec, line, res, target.as_deref());
    DispatchOutcome::Handled
}

/// Runs `line` as the avatar `who` (the issuer of a chat line): builds the context, dispatches, delivers the
/// output to the player. The authority is the stored value of the session (VR-073: never a client-sent value).
pub fn run_player_line(
    svc: &mut Services,
    ctx: &mut GameCtx<'_>,
    who: PlayerRef,
    line: &str,
    shortcut: bool,
) -> DispatchOutcome {
    let Some(a) = crate::chat::actor(ctx, who) else {
        return DispatchOutcome::NotACommand;
    };
    let Some(session) = a.session else {
        return DispatchOutcome::NotACommand;
    };
    let reg = Arc::clone(&svc.gm.registry);
    let mut cx = CmdCtx {
        svc,
        ctx,
        issuer: Issuer::Player {
            session,
            player: who,
        },
        authority: a.authority,
        self_player: Some(who),
        out: CmdOutput::default(),
        shortcut,
    };
    let outcome = dispatch_line(&mut cx, &reg, line);
    let out = std::mem::take(&mut cx.out);
    crate::chat::deliver_lines(ctx, who, out);
    outcome
}

/// 23 §3.6: a line that is not a command. An emote (the whole line equals an emote name, no `#`) and, with
/// `fidelity.unknown_command_as_chat`, every line go on as normal chat; otherwise the same reply for unknown and
/// unauthorised commands, so GM commands are not revealed.
pub fn route_unknown(
    svc: &mut Services,
    ctx: &mut GameCtx<'_>,
    who: PlayerRef,
    line: &str,
) -> Routing {
    if svc.chat.data.emotes.is_emote_line(line) || ctx.cfg.rules.fidelity.unknown_command_as_chat {
        return Routing::AsChat;
    }
    notice::text(ctx, who, UNKNOWN_COMMAND);
    Routing::Replied
}

/// The reply to an unknown or unauthorised command (23 §3.6).
pub const UNKNOWN_COMMAND: &str = "Unknown command. Type /help for the list.";
